        try { return getPreset("in_use"); } catch (e) { console.warn("[erii] getPreset failed", e); }
      }
      const ctx = getCtx(); const s = ctx?.chatCompletionSettings; if (!s) return null;
      const order = (s.prompt_order || []).find((o) => String(o.character_id) === "100001") || s.prompt_order?.[0];
      const byId = new Map((s.prompts || []).map((p) => [p.identifier, p]));
      const prompts = (order?.order || []).map((o) => {
        const p = byId.get(o.identifier) || {};
        return { id: o.identifier, name: p.name || o.identifier, enabled: !!o.enabled, content: p.content || "", role: p.role, _marker: !!p.marker };
      });
      return { prompts, extensions: s.extensions || {}, settings: {}, __fallback: true };
    }

    let writing = false;
    async function mutatePreset(fn, render = "debounced") {
      writing = true;
      try {
        if (helperApi) {
          await updatePresetWith("in_use", (p) => { fn(p); return p; }, { render });
          return true;
        }
        const ctx = getCtx(); const s = ctx?.chatCompletionSettings; if (!s) return false;
        const order = (s.prompt_order || []).find((o) => String(o.character_id) === "100001") || s.prompt_order?.[0];
        const view = { prompts: (order?.order || []).map((o) => ({ id: o.identifier, get enabled() { return !!o.enabled; }, set enabled(v) { o.enabled = !!v; } })), extensions: s.extensions || {} };
        fn(view);
        ctx.saveSettingsDebounced?.();
        return true;
      } finally { setTimeout(() => { writing = false; }, 400); }
    }

    // ------------------------------------------------------------------ 分组解析
    const MARKER_IDS = new Set(["worldInfoBefore", "personaDescription", "charDescription", "charPersonality", "scenario", "worldInfoAfter", "dialogueExamples", "chatHistory", "agentSystemPrompt", "agentResults", "agentTask"]);
    const isMarker = (p) => p._marker || MARKER_IDS.has(p.id);

    function parseGroupTitle(title) {
      const m = /^(.*?)(?:（([^）]*)）)?\s*$/.exec(title.trim());
      const label = (m?.[1] || title).trim();
      const tokens = (m?.[2] || "").split("·").map((t) => t.trim()).filter(Boolean);
      const meta = { label, kind: "check", hidden: false, cont: false, required: false, notes: [] };
      for (const t of tokens) {
        if (t === "互斥") meta.kind = "radio";
        else if (t === "可叠加") meta.kind = "check";
        else if (t === "联动") meta.kind = "bundle";
        else if (t === "隐藏") meta.hidden = true;
        else if (t === "续") meta.cont = true;
        else if (t === "必选") { meta.required = true; meta.notes.push("必选一项"); }
        else meta.notes.push(t);
      }
      return meta;
    }

    const bundleKey = (name) => { const m = /〖(.+?)〗/.exec(name || ""); return m ? m[1] : null; };
    const LEAD_SYMBOL_RE = /^(?:[\u2190-\u21FF\u2300-\u23FF\u2460-\u24FF\u25A0-\u27BF\u2900-\u297F\u2B00-\u2BFF\u3030\u303D\u3297\u3299\uFE0F\u200D\s]|[\uD83C-\uD83E][\uDC00-\uDFFF])+/;
    const displayName = (name) => String(name || "").replace(/〖.+?〗.*$/, "").replace(LEAD_SYMBOL_RE, "").trim();

    // 组内多数条目共享的「前缀·」去掉（游戏模式·普通 → 普通），完整名保留在 title 里
    function shortenLabels(g) {
      const items = g.items.filter((it) => it.type === "item");
      const counts = new Map();
      for (const it of items) { const i = it.label.indexOf("·"); if (i > 0) { const pre = it.label.slice(0, i); counts.set(pre, (counts.get(pre) || 0) + 1); } }
      for (const it of g.items) {
        it.short = it.label;
        const i = it.label.indexOf("·");
        if (i <= 0) continue;
        const pre = it.label.slice(0, i);
        const n = counts.get(pre) || 0;
        if (pre === g.label || (n >= 2 && n * 2 >= items.length)) { const rest = it.label.slice(i + 1).trim(); if (rest) it.short = rest; }
      }
    }

    function buildModel(preset) {
      const prompts = preset.prompts || [];
      const groups = [];
      let cur = null;
      const bundles = new Map();
      for (const p of prompts) {
        const name = p.name || "";
        const dm = /^━━\s*(.+?)\s*━━$/.exec(name);
        if (dm && !(p.content || "").trim()) {
          const meta = parseGroupTitle(dm[1]);
          if (meta.cont && cur) { cur.spans.push(meta.label); continue; }
          cur = { key: meta.label, label: meta.label, kind: meta.kind, hidden: meta.hidden, required: meta.required, notes: meta.notes, items: [], spans: [] };
          groups.push(cur);
          continue;
        }
        if (isMarker(p)) continue;
        if (/^\s*\{\{\/\/[\s\S]*\}\}\s*$/.test(p.content || "")) continue;
        if (/（别动）|（勿关）/.test(name)) continue;
        if (!cur) { cur = { key: "其他", label: "其他", kind: "check", hidden: false, required: false, notes: [], items: [], spans: [] }; groups.push(cur); }
        const bk = bundleKey(name);
        if (bk) {
          let b = bundles.get(bk);
          if (!b) {
            b = { type: "bundle", key: bk, id: "bundle:" + bk, label: displayName(name), full: name, ids: [], members: [] };
            bundles.set(bk, b);
            cur.items.push(b);
          }
          b.ids.push(p.id); b.members.push(p);
          continue;
        }
        cur.items.push({ type: "item", id: p.id, label: displayName(name), full: name, enabled: !!p.enabled, desc: COT_DESC[p.id] || "" });
      }
      for (const b of bundles.values()) {
        const on = b.members.filter((m) => m.enabled).length;
        b.enabled = on === b.members.length && on > 0;
        b.partial = on > 0 && on < b.members.length;
        b.full = b.label + "（联动 " + b.members.length + " 条）";
      }
      for (const g of groups) shortenLabels(g);
      const pairs = EXCLUSIVE_PAIRS.map((x) => [...x]);
      for (const g of groups) {
        for (let i = 0; i < g.items.length - 1; i++) {
          const a = g.items[i], b = g.items[i + 1];
          if (a.type === "item" && b.type === "item" && /与下条.*二选一/.test(a.full) && /与上条.*二选一/.test(b.full)) pairs.push([a.id, b.id]);
        }
      }
      const regexes = (preset.extensions?.regex_scripts || []).filter((r) => String(r.scriptName || "").startsWith(REGEX_TOGGLE_PREFIX));
      const visible = groups.filter((g) => !g.hidden && g.items.length);
      const structureKey = visible.map((g) => g.key + ":" + g.items.map((i) => i.id).join(",")).join("|") + "||" + regexes.map((r) => r.scriptName).join("|");
      return { groups: visible, pairs, regexes, all: prompts, structureKey };
    }

    // ------------------------------------------------------------------ 主题：检测 / 注入
    const THEME_KEY = "theme";
    const BODY_KEY = "bodyTypo";
    const AUTO_TAIL_KEY = "autoTail";

    function parseColor(str) {
      const m = /rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:[,\s/]+([\d.]+))?\s*\)/.exec(str || "");
      if (m) return { r: +m[1], g: +m[2], b: +m[3], a: m[4] == null ? 1 : +m[4] };
      const h = /^#([0-9a-f]{3,8})$/i.exec((str || "").trim());
      if (h) {
        let x = h[1]; if (x.length <= 4) x = x.split("").map((c) => c + c).join("");
        return { r: parseInt(x.slice(0, 2), 16), g: parseInt(x.slice(2, 4), 16), b: parseInt(x.slice(4, 6), 16), a: x.length >= 8 ? parseInt(x.slice(6, 8), 16) / 255 : 1 };
      }
      return null;
    }
    const lum = (c) => (0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b) / 255;

    function detectDark() {
      try {
        const root = getComputedStyle(pdoc.documentElement);
        for (const v of ["--SmartThemeBlurTintColor", "--SmartThemeChatTintColor", "--SmartThemeBodyColor"]) {
          const c = parseColor(root.getPropertyValue(v));
          if (c && c.a > 0.2) return lum(c) < 0.5;
        }
        const chat = pdoc.querySelector("#chat") || pdoc.body;
        const c = parseColor(getComputedStyle(chat).backgroundColor) || parseColor(getComputedStyle(pdoc.body).backgroundColor);
        if (c && c.a > 0.2) return lum(c) < 0.5;
      } catch (_) {}
      try { return !!pwin.matchMedia?.("(prefers-color-scheme: dark)")?.matches; } catch (_) { return false; }
    }

    function applyTheme() {
      const mode = lsGet(THEME_KEY, "auto");
      const resolved = mode === "auto" ? (detectDark() ? "night" : "day") : mode;
      const root = pdoc.documentElement;
      if (root.dataset.eriiTheme !== resolved) {
        root.dataset.eriiTheme = resolved;
        try { pdoc.dispatchEvent(new pwin.CustomEvent("erii:theme", { detail: { theme: resolved, mode } })); } catch (_) {}
      }
      root.dataset.eriiBody = lsGet(BODY_KEY, true) ? "on" : "off";
      root.classList.toggle("erii-night", resolved === "night");
      return resolved;
    }

    // 两套令牌：昼·写字板 / 夜·樱夜（消息卡片、iframe 组件、面板共用）
    const THEME_CSS = `
