    const LOGO = `<svg class="esb-logo" viewBox="0 0 40 40" aria-hidden="true"><g transform="translate(20 20)" fill="#F08CA0"><ellipse cx="0" cy="-9.5" rx="4.6" ry="7.4"/><g transform="rotate(72)"><ellipse cx="0" cy="-9.5" rx="4.6" ry="7.4"/></g><g transform="rotate(144)"><ellipse cx="0" cy="-9.5" rx="4.6" ry="7.4"/></g><g transform="rotate(216)"><ellipse cx="0" cy="-9.5" rx="4.6" ry="7.4"/></g><g transform="rotate(288)"><ellipse cx="0" cy="-9.5" rx="4.6" ry="7.4"/></g><circle r="2.6" fill="#D9A441"/></g></svg>`;
    const petals = Array.from({ length: 12 }, (_, i) => {
      const x = (7 + (i * 37) % 86).toFixed(0);
      const d = (10 + (i % 5) * 1.7).toFixed(1);
      const dl = -((i * 1.9) % 12).toFixed(1);
      const s = 12 + (i % 4) * 3;
      const sw = 10 + (i % 3) * 7;
      const o = (0.55 + (i % 3) * 0.15).toFixed(2);
      return `<span class="esb-p" style="--x:${x}%;--d:${d}s;--dl:${dl}s;--s:${s}px;--sw:${sw}px;--o:${o}"><svg viewBox="0 0 24 24"><path d="${PETAL_PATH}"/></svg></span>`;
    }).join("");

    // ------------------------------------------------------------------ DOM
    const root = pdoc.createElement("div");
    root.id = ID;
    root.innerHTML = `
<div class="esb-backdrop"></div>
<button type="button" class="esb-orb" title="绘梨衣的故事本" aria-label="打开绘梨衣的故事本" aria-expanded="false">${SAKURA}<span class="esb-badge" aria-hidden="true"></span></button>
<div class="esb-panel" role="dialog" aria-label="绘梨衣的故事本" aria-hidden="true">
  <div class="esb-petals" aria-hidden="true">${petals}</div>
  <div class="esb-handle" aria-hidden="true"></div>
  <div class="esb-head">
    ${LOGO}<span class="esb-title">绘梨衣的故事本</span><span class="esb-ver">v${VER}</span>
    <button type="button" class="esb-ibtn esb-theme" title="日 / 夜主题：自动 → 昼 → 夜">◐ 自动</button>
    <button type="button" class="esb-ibtn esb-bodytypo" title="正文轻排版开关（段落呼吸、台词淡底、收尾花纹）">✎ 排版</button>
    <div class="esb-menu">
      <button type="button" class="esb-ibtn esb-profiles" title="方案存档">❀ 方案 ▾</button>
      <div class="esb-dropdown"></div>
    </div>
    <button type="button" class="esb-ibtn esb-close" title="收起" aria-label="收起">✕</button>
  </div>
  <div class="esb-status"></div>
  <div class="esb-tools"><label class="esb-searchwrap"><input type="search" class="esb-search" placeholder="搜索档位…（例：文风 / 字数 / 防）" aria-label="搜索档位"></label></div>
  <div class="esb-body"></div>
  <div class="esb-foot">把故事讲给你听<span class="esb-duck">🦆</span></div>
</div>`;
    (pdoc.body || pdoc.documentElement).appendChild(root);

    const q = (sel) => root.querySelector(sel);
    const orb = q(".esb-orb"), panel = q(".esb-panel"), body = q(".esb-body"), statusEl = q(".esb-status"), search = q(".esb-search");
    const btnTheme = q(".esb-theme"), btnBody = q(".esb-bodytypo"), btnProfiles = q(".esb-profiles"), dropdown = q(".esb-dropdown"), backdrop = q(".esb-backdrop");
    const badge = orb.querySelector(".esb-badge");

    const syncPanelSkin = () => {
      const day = pdoc.documentElement.dataset.eriiTheme === "day";
      root.classList.toggle("esb-day", day);
      root.classList.toggle("esb-night", !day);
    };

    // ------------------------------------------------------------------ 状态
    let model = null;
    let lastPreset = null;
    let builtKey = "";

    async function refreshModel() {
      const p = await readPreset();
      if (!p) { model = null; return null; }
      lastPreset = p;
      model = buildModel(p);
      return model;
    }

    const groupOf = (key) => model?.groups.find((g) => g.key === key || g.label === key);
    const itemEnabled = (id) => !!lastPreset?.prompts?.find((x) => x.id === id)?.enabled;
    const sortGroups = (groups) => {
      const idx = (g) => { const i = GROUP_PRIORITY.indexOf(g.key); return i < 0 ? 999 : i; };
      return [...groups].sort((a, b) => idx(a) - idx(b));
    };

    // ------------------------------------------------------------------ 渲染：结构（只在分组变化时重建）
    const openState = lsGet("openGroups", {});

    function toggleHtml(it, g) {
      const tag = it.type === "bundle" ? `<span class="esb-tag">联动 ${it.ids.length}</span>` : "";
      const role = g.kind === "radio" ? 'role="radio"' : 'role="switch"';
      const label = esc(it.short || it.label);
      const inner = it.desc
        ? `<span class="esb-copy"><span class="esb-lb">${label}</span><span class="esb-desc">${esc(it.desc)}</span></span>${tag}`
        : `<span class="esb-lb">${label}</span>${tag}`;
      return `<button type="button" class="esb-tog" data-id="${esc(it.id)}" data-g="${esc(g.key)}" title="${esc(it.full)}" ${role} aria-checked="false"><span class="esb-led" aria-hidden="true"></span>${inner}</button>`;
    }

    function buildBody() {
      if (!model) {
        body.innerHTML = `<div class="esb-empty">读不到当前预设。<br>请确认酒馆助手已启用、预设脚本已允许运行，且当前预设是「绘绘绘绘绘 ${VER}」。</div>`;
        builtKey = "";
        return;
      }
      const groups = sortGroups(model.groups);
      let html = "";
      for (const g of groups) {
        const mx = g.kind === "radio" ? "单选" : g.kind === "bundle" ? "联动" : "叠加";
        const notes = g.notes.length ? `<span class="esb-note">${esc(g.notes.join(" · "))}</span>` : "";
        const wide = WIDE_GROUPS.has(g.key) || g.items.length > 8 ? " esb-wide" : "";
        const cot = g.key === COT_GROUP_KEY ? " esb-cot" : "";
        const isOpen = openState[g.key] ?? DEFAULT_OPEN.has(g.key);
        const tailAuto = g.key === TAIL_GROUP_KEY ? `<button type="button" class="esb-ibtn esb-autotail" title="按当前 API 自动选尾部">自动</button>` : "";
        const ico = GROUP_ICONS[g.key] || "✿";
        html += `<details class="esb-sec${wide}${cot}" data-g="${esc(g.key)}"${isOpen ? " open" : ""}>
          <summary><span class="esb-ico">${ico}</span><span class="esb-t"><span>${esc(g.label)}</span>${notes}</span>${tailAuto}<span class="esb-cnt"></span><span class="esb-mx">${mx}</span><span class="esb-chev"></span></summary>
          <div class="esb-grid" ${g.kind === "radio" ? 'role="radiogroup"' : ""}>${g.items.map((it) => toggleHtml(it, g)).join("")}</div>
        </details>`;
      }
      const rxRows = model.regexes.map((r) => `<button type="button" class="esb-tog esb-rx" data-rx="${esc(r.scriptName)}" title="${esc(r.scriptName)}"><span class="esb-led"></span><span class="esb-lb">${esc(String(r.scriptName).replace(REGEX_TOGGLE_PREFIX, "").replace(/（.*$/, "").trim())}</span><span class="esb-tag">正则</span></button>`).join("");
      html += `<details class="esb-sec esb-special" data-g="__fx"${openState.__fx ? " open" : ""}>
        <summary><span class="esb-ico">✦</span><span class="esb-t"><span>外观与正则功能</span><span class="esb-note">脚本级 · 立即生效</span></span><span class="esb-mx">工具</span><span class="esb-chev"></span></summary>
        <div class="esb-grid">
          <button type="button" class="esb-tog esb-fx" data-fx="body" title="正文段落排版、台词淡底、收尾花纹"><span class="esb-led"></span><span class="esb-lb">正文轻排版</span><span class="esb-tag">脚本</span></button>
          ${rxRows}
        </div></details>`;
      body.innerHTML = html;
      builtKey = model.structureKey;
      applySearch();
    }

    // ------------------------------------------------------------------ 渲染：状态（原地同步，不重建 DOM）
    function syncStates() {
      if (!model) return;
      const pairBad = new Set();
      for (const [a, b] of model.pairs) if (itemEnabled(a) && itemEnabled(b)) { pairBad.add(a); pairBad.add(b); }
      for (const g of model.groups) {
        const sec = body.querySelector(`details.esb-sec[data-g="${cssEsc(g.key)}"]`);
        if (!sec) continue;
        let onCount = 0;
        for (const it of g.items) {
          const btn = sec.querySelector(`.esb-tog[data-id="${cssEsc(it.id)}"]`);
          if (!btn) continue;
          const on = !!it.enabled, partial = !!it.partial;
          btn.classList.toggle("esb-on", on);
          btn.classList.toggle("esb-partial", partial);
          btn.classList.toggle("esb-bad", pairBad.has(it.id));
          btn.setAttribute("aria-checked", on ? "true" : "false");
          btn.classList.remove("esb-busy");
          if (on || partial) onCount++;
        }
        const bad = g.kind === "radio" && onCount > 1;
        const cnt = sec.querySelector(".esb-cnt");
        if (cnt) { cnt.textContent = bad ? "多开 " + onCount : String(onCount); cnt.classList.toggle("esb-show", onCount > 0); cnt.classList.toggle("esb-bad", bad); }
        const at = sec.querySelector(".esb-autotail");
        if (at) at.classList.toggle("esb-on", !!lsGet(AUTO_TAIL_KEY, true));
      }
      for (const r of model.regexes) {
        const btn = body.querySelector(`.esb-rx[data-rx="${cssEsc(r.scriptName)}"]`);
        if (btn) { btn.classList.toggle("esb-on", !r.disabled); btn.classList.remove("esb-busy"); }
      }
      const fx = body.querySelector('.esb-fx[data-fx="body"]');
      if (fx) fx.classList.toggle("esb-on", !!lsGet(BODY_KEY, true));
    }
    const cssEsc = (s) => (pwin.CSS?.escape ? pwin.CSS.escape(String(s)) : String(s).replace(/["\\]/g, "\\$&"));

    function countProblems() {
      if (!model) return 0;
      let n = 0;
      for (const g of model.groups) { if (g.kind === "radio" && g.items.filter((x) => x.enabled).length > 1) n++; for (const it of g.items) if (it.type === "bundle" && it.partial) n++; }
      for (const [a, b] of model.pairs) if (itemEnabled(a) && itemEnabled(b)) n++;
      return n;
    }

    function renderStatus() {
      if (!model) { statusEl.innerHTML = ""; badge.classList.remove("esb-show"); return; }
      const pick = (key) => { const g = groupOf(key); const on = g?.items.filter((x) => x.enabled) || []; return on.map((x) => x.short || x.label).join(" / "); };
      // 分色规则：每个类别一种颜色；空值变灰（muted）；该有却没有的变红虚线（warn）；模式 / 严格破限 用实心红
      const chip = (label, value, c, state = "", extra = "") => {
        const cls = state ? " esb-" + state : "";
        const styleAttr = state === "warn" ? "" : ` style="--c:var(--c-${c})"`;
        return `<span class="esb-chip${cls}"${styleAttr}><i>${esc(label)}</i><b>${esc(value)}</b>${extra}</span>`;
      };
      const parts = [];
      const mode = pick("输出模式");
      if (mode) parts.push(chip("模式", mode, "mode", "solid"));
      const len = pick("字数"); parts.push(chip("字数", len || "未设", "len", len ? "" : "muted"));
      const sty = pick("文风·通用"); parts.push(chip("文风", sty || "无", "style", sty ? "" : "muted"));
      const cot = pick(COT_GROUP_KEY); parts.push(chip("思维链", cot || "未选", "cot", cot ? "" : "warn"));
      const nsfw = pick("NSFW 强度"); const nsfwOff = !nsfw || /关/.test(nsfw);
      parts.push(chip("NSFW", nsfw || "跟随卡", "nsfw", nsfwOff ? "muted" : ""));
      const tail = pick(TAIL_GROUP_KEY); const auto = lsGet(AUTO_TAIL_KEY, true);
      parts.push(chip("尾部", tail || "无", "tail", tail ? "" : "warn", auto ? "<small>自动</small>" : ""));
      const strict = groupOf("破限")?.items.find((x) => x.type === "bundle");
      if (strict?.enabled) parts.push(chip("严格破限", "开", "mode", "solid"));
      else if (strict?.partial) parts.push(chip("严格破限", "只开了一半", "mode", "warn"));
      const badCount = countProblems();
      if (badCount) parts.push(chip("冲突", badCount + " 处", "mode", "warn"));
      statusEl.innerHTML = parts.join("");
      badge.textContent = String(badCount); badge.classList.toggle("esb-show", badCount > 0);
    }

    function updateHeaderButtons() {
      const mode = lsGet(THEME_KEY, "auto");
      const cur = pdoc.documentElement.dataset.eriiTheme === "night" ? "夜" : "昼";
      btnTheme.textContent = mode === "auto" ? `◐ 自动·${cur}` : mode === "day" ? "☀ 昼" : "☾ 夜";
      btnTheme.classList.toggle("esb-on", mode !== "auto");
      btnBody.classList.toggle("esb-on", !!lsGet(BODY_KEY, true));
    }

    function renderAll() {
      syncPanelSkin();
      if (!model || model.structureKey !== builtKey) {
        const st = body.scrollTop;
        buildBody();
        body.scrollTop = st;
      }
      syncStates();
      renderStatus();
      updateHeaderButtons();
    }

    function applySearch() {
      const kw = search.value.trim().toLowerCase();
      body.querySelectorAll("details.esb-sec").forEach((sec) => {
        let any = false;
        sec.querySelectorAll(".esb-tog").forEach((b) => {
          const hit = !kw || (b.textContent + " " + (b.title || "")).toLowerCase().includes(kw);
          b.classList.toggle("esb-hide", !hit); if (hit) any = true;
        });
        sec.classList.toggle("esb-hide", !!kw && !any);
        if (kw && any) sec.open = true;
      });
    }
    search.addEventListener("input", debounce(applySearch, 80));
    search.addEventListener("keydown", (e) => { if (e.key === "Escape") { search.value = ""; applySearch(); } e.stopPropagation(); });

    // ------------------------------------------------------------------ 开关操作
    async function setEnabled(pairs) {
      const map = new Map(pairs);
      await mutatePreset((p) => { for (const pr of p.prompts) if (map.has(pr.id)) pr.enabled = !!map.get(pr.id); });
    }

    async function toggleItem(gKey, id) {
      const g = groupOf(gKey); if (!g) return;
      const it = g.items.find((x) => x.id === id); if (!it) return;
      const changes = [];
      if (it.type === "bundle") {
        const target = !it.enabled;
        for (const mid of it.ids) changes.push([mid, target]);
      } else if (g.kind === "radio") {
        const target = !it.enabled;
        if (!target && g.required) { toast(`「${g.label}」必须保留一项，直接点别的选项切换即可。`, "info"); return; }
        for (const other of g.items) { if (other.type === "bundle") continue; changes.push([other.id, other.id === id ? target : false]); }
        if (g.key === TAIL_GROUP_KEY && target) lsSet(AUTO_TAIL_KEY, false);
      } else {
        changes.push([id, !it.enabled]);
        for (const [a, b] of model.pairs) {
          if (a === id && !it.enabled) changes.push([b, false]);
          if (b === id && !it.enabled) changes.push([a, false]);
        }
      }
      await setEnabled(changes);
      await refreshModel(); renderAll();
    }

    async function toggleRegex(name) {
      const isFar = name === FAR_MEMO_ON;
      const before = lastPreset?.extensions?.regex_scripts?.find((x) => x.scriptName === name);
      const turningOn = !!before?.disabled;
      await mutatePreset((p) => {
        const list = p.extensions?.regex_scripts || [];
        const r = list.find((x) => x.scriptName === name); if (!r) return;
        r.disabled = !r.disabled;
        if (isFar) { const cleaner = list.find((x) => x.scriptName === FAR_MEMO_OFF_WHEN_ON); if (cleaner) cleaner.disabled = !r.disabled; }
      }, "immediate");
      if (isFar && turningOn && !itemEnabled("memo_fmt")) toast("备忘没开的话，旧楼层里没有备忘卡，「远楼只留备忘」不会生效（会照常发送正文）。请在「格式化输出」里把备忘打开。", "warning");
      await refreshModel(); renderAll();
    }

    let busy = false;
    body.addEventListener("click", async (e) => {
      const at = e.target.closest(".esb-autotail");
      if (at) {
        e.preventDefault(); e.stopPropagation();
        lsSet(AUTO_TAIL_KEY, !lsGet(AUTO_TAIL_KEY, true));
        if (lsGet(AUTO_TAIL_KEY, true)) await autoTail(true);
        renderAll(); return;
      }
      const btn = e.target.closest(".esb-tog"); if (!btn) return;
      if (busy) return;
      if (btn.classList.contains("esb-fx")) { lsSet(BODY_KEY, !lsGet(BODY_KEY, true)); applyTheme(); renderAll(); return; }
      busy = true; btn.classList.add("esb-busy");
      try {
        if (btn.classList.contains("esb-rx")) await toggleRegex(btn.dataset.rx);
        else if (model) await toggleItem(btn.dataset.g, btn.dataset.id);
      } catch (err) { console.error("[erii] toggle failed", err); toast("切换失败：" + (err?.message || err), "error"); }
      finally { busy = false; btn.classList.remove("esb-busy"); }
    });
    body.addEventListener("toggle", (e) => {
      const d = e.target; if (!d || d.tagName !== "DETAILS") return;
      openState[d.dataset.g] = d.open; lsSet("openGroups", openState);
    }, true);

    // ------------------------------------------------------------------ 方案
    function snapshot() {
      const ids = {};
      for (const g of model.groups) for (const it of g.items) {
        if (it.type === "bundle") for (const mid of it.ids) ids[mid] = itemEnabled(mid);
        else ids[it.id] = it.enabled;
      }
      const regex = {};
      for (const r of model.regexes) regex[r.scriptName] = !r.disabled;
      return { ids, regex, body: !!lsGet(BODY_KEY, true), ts: Date.now() };
    }
    async function applySnapshot(s) {
      await mutatePreset((p) => {
        for (const pr of p.prompts) if (pr.id in s.ids) pr.enabled = !!s.ids[pr.id];
        for (const r of p.extensions?.regex_scripts || []) if (r.scriptName in (s.regex || {})) r.disabled = !s.regex[r.scriptName];
      }, "immediate");
      if (typeof s.body === "boolean") { lsSet(BODY_KEY, s.body); applyTheme(); }
    }
    async function applyBuiltin(def) {
      const changes = [];
      for (const [gKey, chosen] of Object.entries(def.radio || {})) {
        const g = groupOf(gKey); if (!g) continue;
        for (const it of g.items) { if (it.type === "bundle") continue; changes.push([it.id, chosen != null && it.id === chosen]); }
      }
      for (const [id, v] of Object.entries(def.check || {})) changes.push([id, !!v]);
      await setEnabled(changes);
    }
    function renderDropdown() {
      const saved = lsGet("profiles", {});
      let html = `<div class="esb-hint">内置组合（只改相关组，其余不动）</div>`;
      for (const name of Object.keys(BUILTIN_PROFILES)) html += `<div class="esb-row" data-builtin="${esc(name)}">✿ ${esc(name)}</div>`;
      html += `<div class="esb-sep"></div><div class="esb-hint">我的方案（保存整套开关）</div>`;
      const names = Object.keys(saved);
      if (!names.length) html += `<div class="esb-hint" style="opacity:.7">还没有保存过</div>`;
      for (const n of names) html += `<div class="esb-row" data-load="${esc(n)}">${esc(n)}<span class="esb-del" data-del="${esc(n)}" title="删除">删</span></div>`;
      html += `<div class="esb-sep"></div><div class="esb-row" data-save="1">＋ 把当前开关保存为方案…</div>`;
      dropdown.innerHTML = html;
    }
    btnProfiles.addEventListener("click", (e) => { e.stopPropagation(); renderDropdown(); dropdown.classList.toggle("esb-show"); });
    const onDocClick = (e) => { if (!e.target.closest?.(`#${ID} .esb-menu`)) dropdown.classList.remove("esb-show"); };
    pdoc.addEventListener("click", onDocClick);
    dropdown.addEventListener("click", async (e) => {
      e.stopPropagation();
      const del = e.target.closest("[data-del]");
      if (del) { const s = lsGet("profiles", {}); delete s[del.dataset.del]; lsSet("profiles", s); renderDropdown(); return; }
      const row = e.target.closest(".esb-row"); if (!row) return;
      try {
        if (row.dataset.builtin) { await applyBuiltin(BUILTIN_PROFILES[row.dataset.builtin]); await refreshModel(); renderAll(); toast(`已套用「${row.dataset.builtin}」组合`, "success"); }
        else if (row.dataset.load) { const s = lsGet("profiles", {})[row.dataset.load]; if (s) { await applySnapshot(s); await refreshModel(); renderAll(); toast(`已载入方案「${row.dataset.load}」`, "success"); } }
        else if (row.dataset.save) {
          const name = pwin.prompt("给这套开关起个名字：", `方案 ${new Date().toLocaleDateString()}`);
          if (!name) return;
          const s = lsGet("profiles", {}); s[name] = snapshot(); lsSet("profiles", s); renderDropdown(); toast(`已保存方案「${name}」`, "success");
        }
      } catch (err) { console.error("[erii] profile failed", err); toast("方案操作失败：" + (err?.message || err), "error"); }
      dropdown.classList.remove("esb-show");
    });

    // ------------------------------------------------------------------ 主题 / 排版按钮
    btnTheme.addEventListener("click", () => {
      const cur = lsGet(THEME_KEY, "auto");
      lsSet(THEME_KEY, cur === "auto" ? "day" : cur === "day" ? "night" : "auto");
      applyTheme(); renderAll();
    });
    btnBody.addEventListener("click", () => { lsSet(BODY_KEY, !lsGet(BODY_KEY, true)); applyTheme(); renderAll(); });

    // ------------------------------------------------------------------ 自动尾部
    const MODEL_KEYS = { openai: "openai_model", claude: "claude_model", openrouter: "openrouter_model", makersuite: "google_model", vertexai: "vertexai_model", custom: "custom_model", deepseek: "deepseek_model", xai: "xai_model", moonshot: "moonshot_model", zai: "zai_model", siliconflow: "siliconflow_model", minimax: "minimax_model", mistralai: "mistralai_model", cohere: "cohere_model", groq: "groq_model", perplexity: "perplexity_model", aimlapi: "aimlapi_model", chutes: "chutes_model", nanogpt: "nanogpt_model", electronhub: "electronhub_model", fireworks: "fireworks_model", cometapi: "cometapi_model", azure_openai: "azure_openai_model", pollinations: "pollinations_model", workers_ai: "workers_ai_model" };

    function apiSignature() {
      const ctx = getCtx(); const s = ctx?.chatCompletionSettings || {};
      const src = String(s.chat_completion_source || "").toLowerCase();
      let modelName = "";
      try { modelName = String(s[MODEL_KEYS[src]] || ctx?.getChatCompletionModel?.() || ""); } catch (_) {}
      const effort = String(s.reasoning_effort || "").toLowerCase();
      return { src, model: modelName.toLowerCase(), effort, sig: `${ctx?.mainApi}|${src}|${modelName}|${effort}` };
    }
    function pickTail({ src, model: m, effort }) {
      const thinking = effort && effort !== "min";
      const isClaude = src === "claude" || /claude/.test(m);
      const isGemini = src === "makersuite" || src === "vertexai" || /gemini|gemma/.test(m);
      const isDomestic = ["deepseek", "zai", "moonshot", "siliconflow", "minimax"].includes(src) || /deepseek|glm|kimi|qwen|minimax|doubao|hunyuan|ernie|spark|yi-|abab|step-|longcat|internlm/.test(m);
      const isGpt = src === "openai" || src === "azure_openai" || /\bgpt|^o[134]|openai/.test(m);
      if (isClaude) return thinking ? TAILS.claude_think : TAILS.claude;
      if (isGemini) return TAILS.gemini;
      if (isDomestic) return TAILS.domestic;
      if (isGpt) return TAILS.gemini;
      return TAILS.claude;
    }
    let lastSig = "";
    async function autoTail(force = false) {
      if (!lsGet(AUTO_TAIL_KEY, true) || !model) return;
      const info = apiSignature();
      if (!force && info.sig === lastSig) return;
      lastSig = info.sig;
      const want = pickTail(info);
      const g = groupOf(TAIL_GROUP_KEY); if (!g) return;
      const known = new Set(Object.values(TAILS));
      const present = g.items.filter((x) => x.type === "item" && known.has(x.id));
      if (!present.some((x) => x.id === want)) return;
      if (present.every((x) => x.enabled === (x.id === want))) return;
      await setEnabled(present.map((x) => [x.id, x.id === want]));
      await refreshModel(); renderAll();
      toast(`预填尾部已按当前 API 切到「${present.find((x) => x.id === want)?.label}」`, "info");
    }

    // ------------------------------------------------------------------ 一次性模式自动归位 / 事件
    async function onGenerationEnded() {
      try {
        await refreshModel(); if (!model) return;
        const off = ONE_SHOT_IDS.filter((id) => itemEnabled(id));
        if (!off.length) { renderAll(); return; }
        await setEnabled(off.map((id) => [id, false]));
        await refreshModel(); renderAll();
        toast("一次性模式已自动关闭，故事接着往下走。", "info");
      } catch (e) { console.warn("[erii] one-shot revert failed", e); }
    }
    const ctx0 = getCtx();
    const ev = ctx0?.eventSource; const et = ctx0?.eventTypes || ctx0?.event_types || {};
    const listeners = [];
    const on = (name, fn) => { const key = et[name] || name; if (ev?.on) { ev.on(key, fn); listeners.push([key, fn]); } };
    on("GENERATION_ENDED", onGenerationEnded);
    on("MESSAGE_RECEIVED", () => setTimeout(applyTheme, 50));
    on("OAI_PRESET_CHANGED_AFTER", () => setTimeout(async () => { await refreshModel(); renderAll(); autoTail(true); }, 300));
    on("CHATCOMPLETION_SOURCE_CHANGED", () => setTimeout(() => autoTail(true), 300));
    on("CHATCOMPLETION_MODEL_CHANGED", () => setTimeout(() => autoTail(true), 300));
    on("SETTINGS_UPDATED", debounce(() => { if (!writing && !busy) refreshModel().then(() => { renderAll(); autoTail(); }); }, 500));

    // ------------------------------------------------------------------ 面板开合
    const setOpen = (open) => {
      root.classList.toggle("esb-open", !!open);
      orb.setAttribute("aria-expanded", String(!!open));
      panel.setAttribute("aria-hidden", String(!open));
      lsSet("open", !!open);
      if (open) refreshModel().then(() => { renderAll(); autoTail(); });
    };
    const isOpen = () => root.classList.contains("esb-open");
    q(".esb-close").addEventListener("click", () => { setOpen(false); orb.focus(); });
    backdrop.addEventListener("click", () => setOpen(false));
    const onKey = (e) => { if (e.key === "Escape" && isOpen()) { setOpen(false); orb.focus(); } };
    pdoc.addEventListener("keydown", onKey);

    // ------------------------------------------------------------------ 拖动与轻点：一次手势只仲裁一次
    const HAS_PE = typeof pwin.PointerEvent === "function";
    const DRAG_THRESHOLD = 8;
    const dragDisposers = [];

    function makeDraggable(el, { key, allow, onEnd, onTap }) {
      let cancelActive = null;
      let ignoreMouseUntil = 0;
      const onDown = (e) => {
        const touch = e.type === "touchstart";
        if (cancelActive || (allow && !allow(e))) return;
        if (HAS_PE && !e.isPrimary) return;
        if (touch && e.touches.length !== 1) return;
        if (!touch && e.button != null && e.button !== 0) return;
        if (e.type === "mousedown" && Date.now() < ignoreMouseUntil) return;
        if (touch) ignoreMouseUntil = Date.now() + 800;
        const start = touch ? e.changedTouches[0] : e;
        const pid = touch ? start.identifier : e.pointerId;
        const sx = start.clientX, sy = start.clientY;
        // offset 尺寸不受球的呼吸/缩放动画影响。
        const rect = { left: el.offsetLeft, top: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight };
        const oldStyle = { left: el.style.left, top: el.style.top, right: el.style.right, bottom: el.style.bottom };
        const moveType = touch ? "touchmove" : HAS_PE ? "pointermove" : "mousemove";
        const upType = touch ? "touchend" : HAS_PE ? "pointerup" : "mouseup";
        const cancelType = touch ? "touchcancel" : "pointercancel";
        let moved = false, finished = false;
        const point = (event) => touch
          ? Array.from(event.changedTouches || []).find((t) => t.identifier === pid)
          : (!HAS_PE || event.pointerId === pid ? event : null);
        const move = (event) => {
          const p = point(event); if (!p || finished) return;
          const dx = p.clientX - sx, dy = p.clientY - sy;
          if (!moved) { if (Math.hypot(dx, dy) < DRAG_THRESHOLD) return; moved = true; el.classList.add("esb-dragging"); }
          el.style.left = clampNum(rect.left + dx, 0, Math.max(0, pwin.innerWidth - rect.width)) + "px";
          el.style.top = clampNum(rect.top + dy, 0, Math.max(0, pwin.innerHeight - rect.height)) + "px";
          el.style.right = "auto"; el.style.bottom = "auto";
          if (event.cancelable) event.preventDefault();
        };
        const finish = (event, cancelled = false) => {
          if (finished || (event && !point(event))) return;
          if (!cancelled && event) move(event); // 快速手势可能没有单独的 move。
          finished = true;
          cancelActive = null;
          pdoc.removeEventListener(moveType, move, true);
          pdoc.removeEventListener(upType, up, true);
          pdoc.removeEventListener(cancelType, cancel, true);
          el.removeEventListener("lostpointercapture", cancel);
          pwin.removeEventListener("blur", blur);
          try { if (HAS_PE && el.hasPointerCapture(pid)) el.releasePointerCapture(pid); } catch (_) {}
          el.classList.remove("esb-dragging");
          if (touch) ignoreMouseUntil = Date.now() + 800;
          if (cancelled) { if (moved) Object.assign(el.style, oldStyle); return; }
          if (event?.cancelable && (touch || event.pointerType === "touch")) event.preventDefault();
          if (moved) {
            if (onEnd) onEnd();
            else lsSet(key, { x: Math.round(parseFloat(el.style.left)), y: Math.round(parseFloat(el.style.top)) });
          } else onTap?.();
        };
        const up = (event) => finish(event);
        const cancel = (event) => finish(event, true);
        const blur = () => finish(null, true);
        cancelActive = blur;
        // 宿主文档监听也覆盖捕获失败和指针移出球的情况。
        pdoc.addEventListener(moveType, move, { capture: true, passive: false });
        pdoc.addEventListener(upType, up, { capture: true, passive: false });
        pdoc.addEventListener(cancelType, cancel, true);
        el.addEventListener("lostpointercapture", cancel);
        pwin.addEventListener("blur", blur);
        try { if (HAS_PE) el.setPointerCapture(pid); } catch (_) {}
        if (touch && e.cancelable) e.preventDefault();
      };
      const downType = HAS_PE ? "pointerdown" : "mousedown";
      el.addEventListener(downType, onDown);
      if (!HAS_PE) el.addEventListener("touchstart", onDown, { passive: false });
      return () => {
        cancelActive?.();
        el.removeEventListener(downType, onDown);
        if (!HAS_PE) el.removeEventListener("touchstart", onDown);
      };
    }

    // 球：只保存一次吸边后的稳定目标，不读取动画中的矩形反写存档。
    const snapOrb = () => {
      const W = pwin.innerWidth, H = pwin.innerHeight, m = 14;
      const left = orb.offsetLeft + orb.offsetWidth / 2 < W / 2 ? m : W - orb.offsetWidth - m;
      const top = clampNum(orb.offsetTop, m, Math.max(m, H - orb.offsetHeight - m));
      orb.style.left = left + "px"; orb.style.top = top + "px";
      orb.style.right = "auto"; orb.style.bottom = "auto";
      lsSet("orbPos", { x: Math.round(left), y: Math.round(top) });
    };
    dragDisposers.push(makeDraggable(orb, { key: "orbPos", onEnd: snapOrb, onTap: () => setOpen(!isOpen()) }));
    orb.addEventListener("click", (e) => {
      // 指针/触摸已在 up 处理；这里仅保留键盘和辅助技术产生的语义点击。
      if (e.detail !== 0 || (e.pointerType && e.pointerId >= 0)) { e.preventDefault(); e.stopPropagation(); return; }
      setOpen(!isOpen());
    });
    orb.addEventListener("dragstart", (e) => e.preventDefault());

    // 面板头：桌面端可拖，手机端不拖（底部抽屉）
    dragDisposers.push(makeDraggable(panel, { key: "panelPos", allow: (e) => !isMobile() && e.target.closest(".esb-head") && !e.target.closest("button,input,.esb-menu") }));


    const clampEl = (el) => {
      const r = el.getBoundingClientRect();
      el.style.left = clampNum(r.left, 0, Math.max(0, pwin.innerWidth - r.width)) + "px";
      el.style.top = clampNum(r.top, 0, Math.max(0, pwin.innerHeight - r.height)) + "px";
      el.style.right = "auto"; el.style.bottom = "auto";
    };
    const restorePos = () => {
      const o = lsGet("orbPos", null);
      if (o && Number.isFinite(o.x) && Number.isFinite(o.y)) { orb.style.left = o.x + "px"; orb.style.top = o.y + "px"; orb.style.right = "auto"; orb.style.bottom = "auto"; clampEl(orb); }
      const pp = lsGet("panelPos", null);
      if (pp && !isMobile() && Number.isFinite(pp.x) && Number.isFinite(pp.y)) { panel.style.left = pp.x + "px"; panel.style.top = pp.y + "px"; panel.style.right = "auto"; panel.style.bottom = "auto"; }
    };
    restorePos();
    const onResize = debounce(() => {
      if (orb.style.left) clampEl(orb);
      if (isMobile()) { panel.style.left = ""; panel.style.top = ""; panel.style.right = ""; panel.style.bottom = ""; }
      else if (panel.style.left) clampEl(panel);
    }, 120);
    pwin.addEventListener("resize", onResize);

    // ------------------------------------------------------------------ 主题跟随
    applyTheme(); syncPanelSkin();
    const themeObserver = new pwin.MutationObserver(debounce(() => { applyTheme(); syncPanelSkin(); updateHeaderButtons(); }, 200));
    try { themeObserver.observe(pdoc.body, { attributes: true, attributeFilter: ["class", "style"] }); themeObserver.observe(pdoc.documentElement, { attributes: true, attributeFilter: ["class", "style"] }); } catch (_) {}
    const themeTick = setInterval(() => { const before = pdoc.documentElement.dataset.eriiTheme; applyTheme(); if (before !== pdoc.documentElement.dataset.eriiTheme) { syncPanelSkin(); updateHeaderButtons(); } }, 4000);
    const tailTick = setInterval(() => { if (model && !busy && !writing) autoTail(); }, 5000);

    // ------------------------------------------------------------------ 启动
    await refreshModel();
    renderAll();
    if (lsGet("open", false) && !isMobile()) setOpen(true);
    setTimeout(() => autoTail(true), 800);
    if (!helperApi) toast("未检测到酒馆助手预设 API，悬浮窗以兼容模式运行（部分功能受限）。", "warning");

    // ------------------------------------------------------------------ 清理（只用 pagehide：unload 已被浏览器权限策略禁止）
    const cleanup = () => {
      for (const dispose of dragDisposers) dispose();
      clearInterval(themeTick); clearInterval(tailTick);
      try { themeObserver.disconnect(); } catch (_) {}
      for (const [k, fn] of listeners) { try { ev?.removeListener?.(k, fn); } catch (_) {} }
      pdoc.removeEventListener("keydown", onKey);
      pdoc.removeEventListener("click", onDocClick);
      pwin.removeEventListener("resize", onResize);
      pdoc.getElementById(ID)?.remove();
      pdoc.getElementById(ID + "-style")?.remove();
      // 主题样式保留：老楼层的卡片还要靠它上色；下一版脚本启动时会替换
    };
    pwin.__eriiStorybook = { cleanup, version: VER };
    try { window.addEventListener("pagehide", cleanup); } catch (_) {}
  };

  // 启动失败时不要静默：控制台 + toastr + 一个会说明原因的红色小球
  const launch = async () => {
    try { await boot(); }
    catch (e) {
      console.error("[erii] 悬浮窗启动失败：", e);
      try {
        let pd, pw;
        try { pd = parent?.document || document; pw = parent?.window || window; } catch (_) { pd = document; pw = window; }
        const msg = String((e && (e.stack || e.message)) || e);
        try { pw.toastr?.error?.(msg.slice(0, 300), "绘梨衣的故事本：启动失败"); } catch (_) {}
        if (pd.getElementById("erii-storybook-fail")) return;
        const b = pd.createElement("button");
        b.id = "erii-storybook-fail"; b.type = "button"; b.textContent = "✿!";
        b.title = "绘梨衣的故事本启动失败，点击查看原因";
        b.style.cssText = "position:fixed;right:18px;bottom:22px;z-index:2147483647;width:48px;height:48px;border-radius:50%;border:2px solid #d4506b;background:#fff8f4;color:#d4506b;font-size:18px;cursor:pointer;box-shadow:0 6px 16px rgba(120,40,60,.3)";
        b.addEventListener("click", () => { pw.alert("绘梨衣的故事本 启动失败：\n\n" + msg); });
        (pd.body || pd.documentElement).appendChild(b);
      } catch (_) {}
    }
  };
  const start = () => { launch(); };
  if (typeof $ === "function" && typeof errorCatched === "function") $(errorCatched(start));
  else if (typeof $ === "function") $(start);
  else if (document.readyState !== "loading") start();
  else document.addEventListener("DOMContentLoaded", start);
})();

